use moloch_live_runtime::throughput_discovery::ReadBudget;
use baal_transport_service::Scope;
use moloch_replay::session::Session;
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::{collections::BTreeSet,path::PathBuf,sync::atomic::{AtomicU64,Ordering}};
const BASE:i64=1_792_054_800_000;
fn iso(t:i64)->String{chrono::DateTime::from_timestamp_millis(BASE+t).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn ids(values:&[&str])->Vec<String>{values.iter().map(|v|v.to_string()).collect()}
fn set(values:&[&str])->BTreeSet<String>{ids(values).into_iter().collect()}
struct F{bank:Session,scope:Scope,root:PathBuf}
impl Drop for F{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.root);}}
impl F{
 fn new(inherited:bool)->Self{static N:AtomicU64=AtomicU64::new(0);let root=std::env::temp_dir().join(format!("throughput-discovery-{}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),N.fetch_add(1,Ordering::Relaxed)));let policy=json!({"initialCash":"40000.000000","maximumCommitted":"40000.000000","maximumMarketCost":"10000.000000","quantity":10000,"maximumMarkets":3,"entryStopAt":iso(3600000)});let seed=json!({"runId":"throughput-fixture","tournamentId":"cup","availableCash":"40000.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let bank=Session::open_live(&root,&policy,&seed).unwrap();let scope=Scope{tournament_id:"cup".into(),tournament_slug:"cup".into(),exchanges:(100..337).map(|n|(n.to_string(),n.to_string())).collect()};let mut f=Self{bank,scope,root};if inherited{f.put(&json!({"type":"actual_position_adoption","source":"official_sig_api_v1","authority":"human_moloch_inherited_management_20261015","complete":true,"receiptHash":"d".repeat(64),"tournamentId":"cup","receivedAt":iso(0),"processedAt":iso(0),"requestStartedAt":iso(0),"openingCost":"5.600000","effectiveMaximumMarkets":31,"positions":(100..128).map(|n|json!({"exchangeId":n.to_string(),"marketId":n.to_string(),"quantity":1,"lotPrincipal":"0.200000","reportedCostBasis":"0.200000","reportedMinusLotPrincipal":"0.000000","basisClassification":"exact","lots":[{"lotId":(n+1000).to_string(),"quantity":1,"side":"YES","entryPrice":"0.200000","openedAt":iso(-1000)}]})).collect::<Vec<_>>()}));}f}
 fn put(&mut self,e:&Value){let n=self.bank.last_source_sequence("fixture")+1;self.bank.accept("fixture",n,e).unwrap();}
 fn extend(&mut self){let old=self.bank.engine().fresh_market_limit();let maximum=self.bank.engine().policy()["maximumMarkets"].as_u64().unwrap();self.put(&json!({"type":"live_market_capacity_v1","source":"moloch_live_dispatcher","authorizationId":"human_moloch_breadth_20261016","receivedAt":iso(0),"processedAt":iso(0),"bankScope":{"runId":"throughput-fixture","bankManifestHash":self.bank.manifest_hash(),"tournamentId":"cup"},"bankHead":self.bank.durable_head(),"expectedReportSha256":hash(&self.bank.engine().report().unwrap()),"expectedPolicySha256":hash(self.bank.engine().policy()),"expectedPreviousFreshMarketLimit":old,"expectedPreviousMaximumMarkets":maximum,"freshMarketLimit":12,"effectiveMaximumMarkets":maximum+12-old as u64,"scopeExchangeIds":self.scope.exchanges.keys().collect::<Vec<_>>(),"controlSha256":"b".repeat(64),"expectedPreviousCapacitySha256":null}));}
}
#[test]fn current_replayed_native_capacity_replaces_original_three_without_spending(){let mut f=F::new(true);assert_eq!(ReadBudget::from_bank(&f.bank,&f.scope).unwrap().maximum_discovery_reads(),3);f.extend();let before=f.bank.engine().report().unwrap();let head=f.bank.durable_head();let budget=ReadBudget::from_bank(&f.bank,&f.scope).unwrap();assert_eq!(budget.maximum_managed_markets(),40);assert_eq!(budget.maximum_discovery_reads(),12);assert_eq!(f.bank.engine().report().unwrap(),before);assert_eq!(f.bank.durable_head(),head);assert!(f.bank.engine().fills().is_empty());}
#[test]fn noninherited_current_capacity_and_legacy_three_both_work(){let mut f=F::new(false);let b=ReadBudget::from_bank(&f.bank,&f.scope).unwrap();assert_eq!(b.maximum_managed_markets(),3);assert_eq!(b.maximum_discovery_reads(),3);f.extend();let b=ReadBudget::from_bank(&f.bank,&f.scope).unwrap();assert_eq!(b.maximum_managed_markets(),12);assert_eq!(b.maximum_discovery_reads(),12);}
#[test]fn owned_nineteen_plus_twelve_fresh_are_all_retained_with_early_discovery(){let mut f=F::new(true);f.extend();let b=ReadBudget::from_bank(&f.bank,&f.scope).unwrap();let required:BTreeSet<_>=(100..128).map(|n|n.to_string()).collect();let mut selected:Vec<_>=(100..119).map(|n|n.to_string()).collect();selected.extend((200..212).map(|n|n.to_string()));let order=b.order(&selected,&required,&BTreeSet::new());assert_eq!(order.diagnostic,None);assert_eq!(&order.scopes[..5],&ids(&["200","100","201","101","202"]));assert_eq!(order.scopes.len(),31);assert_eq!(order.scopes.iter().cloned().collect::<BTreeSet<_>>(),selected.iter().cloned().collect());let owned:Vec<_>=order.scopes.iter().filter(|ex|required.contains(*ex)).cloned().collect();assert_eq!(owned,(100..119).map(|n|n.to_string()).collect::<Vec<_>>());let fresh:Vec<_>=order.scopes.iter().filter(|ex|!required.contains(*ex)).cloned().collect();assert_eq!(fresh,(200..212).map(|n|n.to_string()).collect::<Vec<_>>());}
#[test]fn urgent_selected_owned_prefix_preserves_all_partition_orders(){let f=F::new(false);let b=ReadBudget::from_bank(&f.bank,&f.scope).unwrap();let order=b.order(&ids(&["100","101","200"]),&set(&["100","101"]),&set(&["101"]));assert_eq!(order.diagnostic,None);assert_eq!(order.scopes,ids(&["101","200","100"]));}
#[test]fn missing_rotated_urgent_owned_is_not_invented_or_added(){let mut f=F::new(true);f.extend();let b=ReadBudget::from_bank(&f.bank,&f.scope).unwrap();let required=f.bank.engine().required_exchanges();let order=b.order(&ids(&["100","200"]),&required,&set(&["127"]));assert_eq!(order.diagnostic,None);assert_eq!(order.scopes,ids(&["200","100"]));}
#[test]fn owned_only_fresh_only_and_empty_do_not_create_reads(){let f=F::new(false);let b=ReadBudget::from_bank(&f.bank,&f.scope).unwrap();for(selected,required)in [(ids(&["100","101"]),set(&["100","101"])),(ids(&["200","201"]),BTreeSet::new()),(vec![],BTreeSet::new())]{let order=b.order(&selected,&required,&BTreeSet::new());assert_eq!(order.diagnostic,None);assert_eq!(order.scopes,selected);}}
#[test]fn invalid_selection_is_complete_original_fallback_not_silent_dropped_owned(){let f=F::new(false);let b=ReadBudget::from_bank(&f.bank,&f.scope).unwrap();for(selected,required,urgent)in [(ids(&["100","100"]),set(&["100"]),BTreeSet::new()),(ids(&["100","999"]),set(&["100"]),BTreeSet::new()),(ids(&["100","200"]),set(&["100"]),set(&["200"])),(ids(&["100"]),set(&["999"]),BTreeSet::new()),(ids(&["100","101","102","103"]),set(&["100","101","102","103"]),BTreeSet::new())]{let order=b.order(&selected,&required,&urgent);assert!(order.diagnostic.is_some());assert_eq!(order.scopes,selected);}}
#[test]fn omitted_actual_owned_set_cannot_be_treated_as_fresh_discovery(){let mut f=F::new(true);f.extend();let b=ReadBudget::from_bank(&f.bank,&f.scope).unwrap();let selected=ids(&["100","200"]);let order=b.order(&selected,&set(&["100"]),&BTreeSet::new());assert_eq!(order.scopes,selected);assert_eq!(order.diagnostic,Some("THROUGHPUT_DISCOVERY_SELECTION_SCOPE"));}
#[test]fn too_many_fresh_reads_falls_back_without_raising_authorized_capacity(){let mut f=F::new(true);f.extend();let b=ReadBudget::from_bank(&f.bank,&f.scope).unwrap();let required=f.bank.engine().required_exchanges();let selected=(200..213).map(|n|n.to_string()).collect::<Vec<_>>();let order=b.order(&selected,&required,&BTreeSet::new());assert_eq!(order.scopes,selected);assert_eq!(order.diagnostic,Some("THROUGHPUT_DISCOVERY_SELECTION_CAPACITY"));}
#[test]fn foreign_tournament_or_owned_scope_is_rejected(){let f=F::new(true);for case in ["tournament","held","small","malformed"]{let mut scope=f.scope.clone();match case{"tournament"=>scope.tournament_id="other".into(),"held"=>{scope.exchanges.remove("100");},"small"=>scope.exchanges=(100..110).map(|n|(n.to_string(),n.to_string())).collect(),_=>{scope.exchanges.insert("01".into(),"201".into());}}assert!(ReadBudget::from_bank(&f.bank,&scope).is_err(),"{case}");}}
#[test]fn actual_unretired_ordinary_draft_market_binding_is_checked(){let mut f=F::new(false);f.put(&json!({"type":"book","receivedAt":iso(0),"book":{"marketId":"200","exchangeId":"200","tournamentId":"cup","sequence":"1","sourceAt":iso(0),"requestStartedAt":iso(0),"receivedAt":iso(0),"bids":[{"price":"0.400000","quantity":10}],"asks":[{"price":"0.450000","quantity":10}]}}));assert!(!f.bank.engine().order_records().is_empty());assert!(ReadBudget::from_bank(&f.bank,&f.scope).is_ok());let mut wrong=f.scope.clone();wrong.exchanges.insert("200".into(),"201".into());assert!(ReadBudget::from_bank(&f.bank,&wrong).is_err());}
